<?php

namespace SaasAgent\AgentStore\Security;

/**
 * The secret pair an integration runs on. See ADR 0009.
 *
 * - requestSecret signs SaaS → store requests.
 * - webhookSecret signs store → SaaS events.
 *
 * Generated by the SaaS during pairing and rotation. Never logged; __debugInfo
 * hides both secrets from dumps and exception traces.
 */
final readonly class Credentials
{
    public function __construct(
        public string $keyId,
        #[\SensitiveParameter] public string $requestSecret,
        #[\SensitiveParameter] public string $webhookSecret,
    ) {
        if (! preg_match('/\Aak_[a-f0-9]{24}\z/', $keyId)) {
            throw new \InvalidArgumentException('Malformed key id.');
        }

        foreach ([$requestSecret, $webhookSecret] as $secret) {
            if (strlen($secret) < 43) {
                throw new \InvalidArgumentException('Secrets must carry at least 256 bits.');
            }
        }
    }

    public static function generate(): self
    {
        return new self(
            'ak_'.bin2hex(random_bytes(12)),
            self::secret(),
            self::secret(),
        );
    }

    private static function secret(): string
    {
        return rtrim(strtr(base64_encode(random_bytes(32)), '+/', '-_'), '=');
    }

    public function __debugInfo(): array
    {
        return ['keyId' => $this->keyId, 'requestSecret' => '[hidden]', 'webhookSecret' => '[hidden]'];
    }
}
